insert into public.preguntas (curso, tema, pregunta, opciones, correcta, explicacion, inventada) values
('PIR 15', 'Pregunta 1', 'En un diseño cuasi-experimental de cohortes:', '["La cohorte anterior al grupo experimental hace las funciones de grupo de control no equivalente.", "Podemos concluir relaciones de causalidad entre las variables en estudio.", "No se puede introducir una intervención como variable independiente porque solo aplicable para el estudio de fenómenos naturales.", "Debemos obtener una amplia serie temporal de medidas pre y post para poder destacar la amenaza de la selección diferencial."]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 2', '¿Qué condiciones debe cumplir una muestra de participantes de un estudio para que sea representativa de la población?:', '["Que se haya obtenido por aplicación de un muestreo de juicio o selección experta.", "Que su tamaño sea suficiente y se haya conseguido que las variables que caracterizan a la población estén presentes en la muestra.", "Que los criterios de inclusión y exclusión en la muestra sean conocidos y públicos.", "Que la población objetivo sea lo más cercana posible a la población."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 3', 'En el contraste estadístico X² (chi cuadrado) la frecuencia teórica es:', '["La frecuencia esperada.", "La frecuencia observada.", "La diferencia entre la frecuencia observada y la esperada.", "La frecuencia que se obtiene en la tabla de la distribución X²."]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 4', 'El nivel de significación (α) suele ser un valor:', '["Muy pequeño porque cuanto menor es α mayor es la probabilidad de rechazar erróneamente la hipótesis nula.", "Muy pequeño porque cuanto mayor es α mayor es la probabilidad de rechazar erróneamente la hipótesis nula.", "Muy grande porque cuanto mayor es α mayor es la probabilidad de rechazar la hipótesis nula.", "Muy pequeño porque cuanto menor es α menor es la probabilidad de rechazar erróneamente la hipótesis nula."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 5', 'La distribución T se aproxima a la normal:', '["A medida que aumentan los grados de libertad.", "Nunca, porque son dos distribuciones distintas.", "Cuando tenemos entre 0 y 30 grados de libertad.", "Si el muestreo es aleatorio."]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 6', '¿Cuál de estas afirmaciones es correcta?:', '["Cuanto menor es la varianza de la distribución muestral del estimador, mayor es la eficiencia.", "Cuanto mayor es la varianza de la distribución muestral del estimador, mayor es la eficiencia.", "Cuanto mayor es la varianza de la distribución muestral del estimador, mayor es la eficacia.", "Cuanto menor es la varianza de la distribución muestral del estimador, menor es la eficacia."]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 7', 'La zona de rechazo de la hipótesis nula se llama:', '["Región β o de rechazo.", "Región crítica o de rechazo.", "Región de confianza o de rechazo.", "Región 1-α o de rechazo."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 8', 'La existencia de una asociación estadística significativa entre variables ordinales puede determinarse, más adecuadamente, mediante:', '["El test de Kuskal-Wallis.", "La correlación de Pearson.", "El test de Kappa.", "La correlation de Spearman."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 9', 'Una puntuación típica normalizada igual a cero, deja por debajo de sí:', '["El 0% de los casos.", "El 50% de los casos.", "El 100% de los casos.", "El 25% de los casos."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 10', 'Para calcular el coeficiente de validez, la correlación más adecuada cuando las puntuaciones del test son una variable continua y el criterio es una variable dicotómica es:', '["La correlación tetracórica.", "El coeficiente phi.", "La correlación de Spearman.", "La correlación biserial puntual."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 11', 'En el estudio de la fiabilidad de un test, los métodos basados en la división del test en dos mitades miden:', '["La estabilidad de las medidas del test.", "La equivalencia de las medidas del test.", "La consistencia interna del test.", "El error de medida del test."]'::jsonb, 2, null, false),
('PIR 15', 'Pregunta 12', 'La dependencia/independencia de campo es:', '["Un rasgo de personalidad bipolar relativo a la autonomía social.", "Un estilo cognitivo vinculado a la percepción con implicaciones en campos diversos como el aprendizaje.", "Una capacidad intelectual necesaria para la toma de decisiones en la resolución de problemas cognitivos complejos.", "Un componente básico de la Teoría Tríadica de la Inteligencia de Sternberg, relativo al mundo interno de la persona."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 13', '¿Cuáles son las aptitudes relacionadas con el mundo externo, que R.J. Sternberg propone en su Teoría Triárquica de la Inteligencia?:', '["La habilidad para manejar la novedad y automatizar procesos.", "Los componentes de ejecución, dirigidos a ejecutar la relación con el mundo externo.", "Los componentes de adquisición del conocimiento que se aprenden en contacto con el mundo externo.", "La capacidad de adaptarse, modificar y seleccionar el ambiente."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 14', 'Se denomina modelo cúbico de la Estructura del Intelecto o de la Inteligencia:', '["Al modelo de capacidades primarias propuesto por Thurstone.", "Al modelo de capacidades independientes propuesto por J.P. Guilford.", "A la estructura jerárquica tridimensional que presenta la inteligencia.", "Al modelo más defendido en la actualidad por autores relevantes en el estudio de la estructura de la inteligencia."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 15', '¿Qué diseño de la Genética de la conducta permite aislar de forma más precisa los efectos ambientales de los efectos genéticos?:', '["Los estudios de adopciones.", "Los estudios comparativos de gemelos monozigóticos y dizigóticos.", "Los estudios de hermanos que viven juntos y separados.", "Los estudios de grupos familiares que presentan distintos grados de parentesco."]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 16', '¿Qué inteligencia implica flexibilidad, capacidad de adaptación y afrontamiento de situaciones nuevas, sin que el aprendizaje previo sea determinante en su manifestación?:', '["La Inteligencia Fluida, Gf.", "Fundamentalmente, el factor de Inteligencia General, g.", "La Inteligencia Cristalizada, Gc.", "La Inteligencia Adaptativa, GAd."]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 17', 'Los cinco superfactores del Modelo de personalidad de los Cinco Grandes surgen de:', '["Un enfoque teórico apriorístico, como el modelo de tres factores de H.J. Eysenck.", "Un enfoque léxico, como en el caso del modelo de R.B. Cattell.", "La combinación de una aproximación factorial, en primer lugar, seguida de una léxica.", "La combinación de una aproximación léxica, en primer lugar, seguida de una factorial."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 18', '¿Qué son el optimismo y el pesimismo defensivo?:', '["Dos tipos de expectativas de autoeficacia propuestos por Bandura.", "Dos tipos de unidades cognitivas propuestas por Mischel.", "Dos tipos de atribuciones propuestas por Weiner.", "Dos tipos de estrategias cognitivas propuestas por Cantor y Norem."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 19', 'Aunque en el control neural del refuerzo pueden intervenir diversos neurotransmisores, las neuronas que desempeñan un papel particularmente importante son:', '["Las neuronas colinérgicas de la protuberancia dorsolateral.", "Las neuronas dopaminérgicas de los sistemas mesolímbico y mesocortical.", "Las neuronas adrenérgicas del bulbo raquídeo.", "Las neuronas colinérgicas del prosencéfalo basal."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 20', 'Según las investigaciones derivadas del modelo de Eysenck, existen evidencias de que los extravertidos, en comparación con los introvertidos:', '["Rinden mejor en tareas de vigilancia.", "Tienen mayor secreción salivar ante la prueba del zumo de limón.", "Tienen mayor necesidad de estimulación.", "Tienen menor tolerancia al dolor."]'::jsonb, 2, null, false),
('PIR 15', 'Pregunta 21', 'De acuerdo con el modelo de los Cinco Grandes ¿En qué dimensión puntuaría alto una mujer imaginativa, creativa, interesada por las ideas y experiencias nuevas?:', '["Actividad.", "Apertura.", "Extraversión.", "Búsqueda de Sensaciones Impulsiva."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 22', '¿En qué dimensión se incluye la impulsividad en el modelo de los Cinco Grandes?:', '["Neuroticismo.", "Extraversión.", "Responsabilidad.", "Amabilidad."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 23', '¿Cuál de las siguientes afirmaciones es correcta en general, respecto al bienestar y la satisfacción con la vida?:', '["La personalidad no está relacionada con la felicidad.", "Hay una relación inversa entre el estatus socio-económico y el bienestar subjetivo.", "Las personas extrovertidas tienden a sentirse más felices que las introvertidas.", "No existe relación entre el componente genético y el bienestar subjetivo."]'::jsonb, 2, null, false),
('PIR 15', 'Pregunta 25', 'La Inteligencia Fluida, propuesta por R.B. Cattell, engloba aptitudes como:', '["La compresión verbal y la riqueza de vocabulario.", "Las relaciones semánticas.", "Los conocimientos mecánicos.", "Las relaciones y clasificaciones figurativas."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 26', 'El Test de Apercepción Temática (TAT) de Murray es una técnica de evaluación:', '["Objetiva.", "Subjetiva y de juego.", "Proyectiva.", "Experimental."]'::jsonb, 2, null, false),
('PIR 15', 'Pregunta 27', 'En la evaluación psicológica, los autorregistros podemos considerarlos como instrumentos:', '["Estructurados.", "Semiestructurados.", "No estructurados.", "Cuasi-experimentales."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 28', 'El “Test de la Figura Humana” (DAP) es una técnica de evaluación proyectiva:', '["Estructural.", "Temática.", "Asociativa.", "Expresiva."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 29', 'El término “Psicodiagnóstico” fue acuñado por:', '["Rorschach y proviene de la tradición semántica médica.", "Cattell y proviene de la tradición semántica psicológica.", "Cronbach y proviene de la tradición semántica estadística.", "Rogers y proviene de la tradición semántica de la filosofía."]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 30', 'El test BETA (Revisado) (Kellog y Morton, 1999):', '["No aporta una puntuación de CI.", "No mide la capacidad verbal, pero está altamente influenciado por ella.", "Se puede aplicar a personas con un nivel cultural muy bajo.", "Consta de 16 subtests."]'::jsonb, 2, null, false),
('PIR 15', 'Pregunta 31', 'En evaluación psicológica la entrevista inicial tiene como principal objetivo:', '["Realizar el diagnostico.", "Identificar y clarificar la demanda.", "Concluir la anamnesis.", "Pasarle la mayor cantidad de test pertinentes en el tiempo disponible."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 32', 'Si queremos evaluar la inteligencia en un niño de 10 años, podríamos utilizar una de las siguientes escalas Wechsler:', '["WPPSI.", "WISC-IV.", "WAIS-III.", "WIPSI."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 33', 'Las escalas McCarthy para niños (MSCA):', '["No incluyen una escala general cognitiva.", "Se aplican a partir de los 8 años y medio.", "Incluyen una escala de psicomotricidad.", "Se aplican de forma colectiva, por lo que son de utilidad en el ámbito escolar."]'::jsonb, 2, null, false),
('PIR 15', 'Pregunta 34', 'Las escalas Bayley de desarrollo infantil (BSID) se aplican:', '["Durante los primeros 2 años y medio de vida.", "Desde los 4 hasta los 6 años.", "Desde los 4 hasta los 10 años.", "Desde el primer mes de vida hasta los 10 años."]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 35', 'El concepto de Evaluación del Potencial de Aprendizaje (PA) o Evaluación Dinámica (ED) trata de comprender el desarrollo cognitivo y el potencial de aprendizaje por medio de factores:', '["Biológicos.", "Psicopatológicos.", "Internos y lógicos.", "Socioculturales."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 36', 'Los instrumentos de evaluación para el screening (cribado) del desarrollo de los niños pretenden:', '["Proporcionar una medida de inteligencia global.", "Evaluar las habilidades específicas.", "Identificar a aquellos niños que tienen una alta probabilidad de padecer un desarrollo retrasado.", "Diagnosticar a los niños con un desarrollo intelectual aventajado."]'::jsonb, 2, null, false),
('PIR 15', 'Pregunta 37', 'Según el modelo propuesto por J.P. Guilford, la evaluación de la inteligencia debe realizarse:', '["Midiendo la inteligencia general (o factor g).", "Estudiando la atención, la memoria y el razonamiento.", "Siguiendo el enfoque de los estilos cognitivos.", "Basándose en la medición de los contenidos, operaciones y producciones de las personas evaluadas."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 38', 'La Teoría Triárquica de la Inteligencia formulada por R.J. Sternberg engloba la subteoría componencial, que se refiere a:', '["Formas de resolución lógica en actividades que requieren abstracción.", "Habilidades comprometidas con la capacidad creativa.", "Habilidades vinculadas al manejo de la vida cotidiana.", "Actividades vinculadas a la capacidad de adaptación emocional."]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 39', 'Uno de los tests más utilizados en la evaluación neuropsicológica del deterioro cognitivo general es:', '["Mini-Menal State Examination (MMSE) de Folstein (1975).", "Geratric Scale (GS) de Yesavage (1983).", "WISC-IV de Welcher (2005).", "Batería de Evaluación del Potencial de Aprendizaje en Demencias (BEPAD) (Fernández Ballesteros et al., 2003)"]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 40', 'El Conner Performance Test-II (CPT-II) (Conner, 2004) es un cuestionario destinado a medir:', '["La memoria.", "La atención y la impulsividad.", "La capacidad verbal y numérica.", "La depresión."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 41', 'En las últimas décadas y en relación con los test de aptitud y/o logro, la teoría clásica de los tests está siendo sustituida por:', '["La teoría del conglomerado.", "La teoría de la respuesta al ítem.", "La teoría ipsativa.", "Las técnicas objetivas."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 42', 'En una interacción comunicativa dirigida a la evaluación psicológica podemos decir, como criterio general, que el cómputo final de palabras del evaluador debe ser:', '["Inferior a las del evaluado.", "Igual que las del evaluado.", "Superior a las del evaluado.", "El máximo posible."]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 43', 'El “Test del Marco y la Varilla” es más propiamente una técnica de evaluación:', '["Objetiva.", "Táctil.", "Proyectiva.", "Auditiva."]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 44', 'En el ámbito de los procesos de selección de personal, los Assessment Center son:', '["Entrevistas estructuradas.", "Test individuales de lápiz y papel.", "Test colectivos utilizados como primer cribado.", "Procedimientos que implican la observación comportamental en situaciones laborales creadas al efecto."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 45', 'En la evaluación psicológica las “escalas de apreciación y protocolos de conducta” recogen:', '["Cualquier tipo de conductas producidas en un tiempo establecido de antemano.", "Un tipo de conducta en un tiempo no establecido.", "Una conducta previamente especificada en un tiempo establecido de antemano.", "Un continuo de las conductas tal y como se producen en su ambiente natural, sin sistematización alguna."]'::jsonb, 2, null, false),
('PIR 15', 'Pregunta 47', 'El “tiempo de Inspección” (TI) puede considerarse, más propiamente, una medida de:', '["La eficiencia neural.", "La memoria.", "El neuroticismo.", "La dependencia /independencia de campo."]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 48', 'Los modelos estructurales de la inteligencia y su medida a través de acercamiento psicométricos:', '["Nos proporcionan un conocimiento basado en los procesos cognitivos utilizados por la persona evaluada.", "Nos revelan el funcionamiento de la inteligencia.", "Permiten elaborar estrategias de intervención efectivas.", "Tienen como objetivo situar al sujeto en una posición dada, dentro de un grupo normativo."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 49', 'Si evaluamos la personalidad partiendo de tres dimensiones: Extraversión/Introversión, Neuroticismo/Estabilidad y Psicoticismo/Control de impulsos, estamos tomando como base el modelo de:', '["R.B. Cattell.", "H.J. Eysenck.", "C.R. Cloninger.", "J.B. Carroll."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 50', 'El uso de un instrumento que evalúe el grado de sugestionabilidad es de utilidad en el diagnóstico diferencial de:', '["Es trastorno obsesivo compulsivo (TOC).", "Los problemas disociativos.", "La ansiedad generalizada.", "Los trastornos de personalidad."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 51', '¿Cuál de las siguientes alteraciones del lenguaje NO es característica de los niños con autismo?:', '["La inversión pronominal.", "La ecolalia.", "Las dificultades con el uso pragmático y social del lenguaje.", "La dificultad persistente en la producción fonológica."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 52', '¿Cuál es la afirmación correcta acerca de la prevalencia de la depresión en la infancia y la adolescencia?:', '["Entre los 6 y los 12 años la prevalencia es muy superior en las niñas.", "En la adolescencia, la depresión es mucho más frecuente en las chicas que en los chicos.", "En la adolescencia, la depresión tiene una prevalencia muy similar en las chicas y en los chicos.", "La prevalencia de la depresión es similar en los adolescentes y en los niños más pequeños."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 53', '¿Cuál es la respuesta correcta acerca de los factores orgánicos en el retraso mental?:', '["Son especialmente importantes en los niveles más graves de retraso.", "No se consideran como tales aquellos que actúan después del nacimiento.", "Su influencia se demuestra por la distribución normal del Cociente Intelectual en la población.", "Cuando son hereditarios, implican siempre genes múltiples."]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 54', '¿Cuál de los siguientes síntomas NO se considera una manifestación de Trastorno obsesivo compulsivo en la infancia?:', '["Las compulsiones de comprobación.", "La lentitud excesiva asociada a la necesidad de simetría.", "Los pensamientos intrusivos obsesivos sin compulsiones.", "Los rituales evolutivos que no causan interferencia."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 55', '¿Cuál de las siguientes NO es una característica de las conductas estereotipadas?:', '["Ser repetitiva y rítmica.", "Ser invariable en topografía (manifestación física).", "Ser rara y excesiva en frecuencia, tasa o amplitud.", "Ser inconsistente y en todo caso inofensiva para el propio sujeto."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 56', '¿Cuál de los siguientes síntomas se considera nuclear para el diagnóstico de la dislexia evolutiva superficial?:', '["El deterioro en la lectura de pseudopalabras en comparación con la de palabras.", "La aparición concomitante de afasia.", "Las palabras regulares, aunque sean desconocidas, tienen mayor probabilidad de ser leídas correctamente que las palabras irregulares.", "La aparición de paralexias visuales y derivativas."]'::jsonb, 2, null, false),
('PIR 15', 'Pregunta 57', 'Desde el modelo conductual ¿Qué mecanismo de aprendizaje se ha propuesto como principal mecanismo mantenedor del mutismo selectivo?:', '["El refuerzo positivo.", "El refuerzo negativo.", "El castigo positivo.", "El modelado."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 58', '¿En qué casos de rechazo escolar debe realizarse el diagnóstico de Fobia específica?:', '["Cuando el miedo, la ansiedad o la evitación sea persistente y dure 6 meses o más.", "Cuando el rechazo a acudir a la escuela sea persistente y genere malestar clínicamente significativo o deterioro en los social, académico o familiar.", "Siempre que no se deba a un trastorno de ansiedad por separación.", "En aquellos en los que el estímulo fóbico sea un aspecto concreto del contexto escolar."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 59', '¿Qué dos grandes categorías de síndromes distingue la clasificación empírica de la psicopatología infantil promovida por Achenbach?:', '["Trastornos afectivos y trastornos de conducta.", "Trastornos socializados y trastornos no socializados.", "Trastornos internalizados y externalizados.", "Retraimiento y problemas sociales."]'::jsonb, 2, null, false),
('PIR 15', 'Pregunta 60', '¿Qué efecto tiene la depresión de los progenitores en la psicopatología de los hijos durante su infancia?:', '["Aumenta el riesgo de padecer trastornos afectivos pero no el de padecer trastornos de ansiedad.", "Impide desarrollar una relación de apego seguro con el progenitor.", "Aumenta de forma específica la probabilidad de padecer un trastorno de conducta debido a la alteración de la crianza.", "Sus consecuencias negativas se manifiestan en múltiples áreas del funcionamiento del niño."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 61', 'Según el DSM (IV-TR y 5) ¿Cuál de los siguientes es requisito para diagnosticar Trastorno de la Tourette?:', '["Un inicio de los síntomas anterior a los 12 años.", "Que los tics motores y los tics vocales hayan estado presentes en algún momento de la enfermedad de forma concurrente.", "Que los tics persistan durante más de un año desde la aparición del primer tic.", "Que hayan estado presentes al menos 3 tics vocales."]'::jsonb, 2, null, false),
('PIR 15', 'Pregunta 62', 'Un niño de 16 meses decía “papa” (patata) para referirse a cualquier fruta o verdura redonda ¿Cómo se denomina esta aplicación de una palabra a mas objetos de los que incluye su significado convencional?:', '["Restricción semántica.", "Aliteración semántica.", "Infraexclusividad semántica.", "Sobreextensión semántica."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 63', 'Un adolescente, ante la pregunta de por qué NO puede robar, contesta “porque pueden verte, denunciarte a la policía y podrías ir a la cárcel”. Según Kohlberg ¿Qué nivel de desarrollo moral está demostrando ese adolescente?:', '["Convencional.", "Preconvencional.", "Orientado a la ley.", "Orientado a principios individuales."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 64', 'Respecto al sentido de la vista en los bebes nacidos ¿Qué afirmación es cierta?:', '["Los bebés nacen prácticamente ciegos.", "Los bebés enfocan coordinadamente los dos ojos (visión bionocular) desde el nacimiento.", "De los cinco sentidos, el de la vista es el menos maduro en el momento del nacimiento.", "Los bebés tienen especiales problemas para enfocar objetos que están entre 6 y 75 cm."]'::jsonb, 2, null, false),
('PIR 15', 'Pregunta 65', 'Muchos adolescentes piensan que son especiales, que tienen una vida excepcional o que lo que les sucede es único y no ha sido experimentado por nadie antes ¿Cómo se denomina este sesgo egocéntrico particularmente frecuente en la adolescencia?:', '["Sesgo de la unicidad.", "Audiencia imaginaria.", "Fábula personal.", "Sesgo de autoengrandecimiento."]'::jsonb, 2, null, false),
('PIR 15', 'Pregunta 66', 'Un bebe de seis meses ha aprendido a coger el sonajero y lo agita para que suene. El resultado le gusta y lo vuelve a agitar repetidamente. Este comportamiento es un ejemplo típico de:', '["Reacción circular secundaria.", "Asimilación.", "Reacción circular terciaria.", "Acomodación."]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 67', 'A diferencia de la inteligencia cristalizada ¿Cuál de las siguientes características presenta la inteligencia fluida?', '["Sus puntuaciones dependen mucho del diseño del estudio, siendo más optimistas en estudios con diseños transversales.", "Implica conocimientos sensibles al contexto cultural.", "Presenta puntuaciones que suelen incrementarse en la adultez media y vejez.", "Alcanza su nivel máximo en la adultez temprana y luego sus puntuaciones suelen decrecer."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 68', 'Uno de los elementos característicos del tratamiento cognitivo del Trastorno Obsesivo Compulsivo, es:', '["Que el paciente asuma o admita como normales las interpretaciones y valoraciones disfuncionales que mantiene sobre sus obsesiones.", "Que el terapeuta se convierta en la principal, y a ser posible, única fuente de reaseguración para el paciente.", "Favorecer que el paciente interprete como “ruido” sus obsesiones y pueda “dejarlas ir” sin procesarlas activamente ni buscarles un significado especial.", "Centrar el foco del tratamiento en los contenidos de las obsesiones para rebatirlos."]'::jsonb, 2, null, false),
('PIR 15', 'Pregunta 69', 'En el tratamiento conductual del Trastorno Obsesivo Compulsivo, la técnica de la exposición con prevención de respuesta tiene como finalidad que el paciente:', '["Se habitúe a la ansiedad que le causan las obsesiones sin utilizar estrategias para neutralizarla o disminuirla.", "Aprenda a suprimir de manera eficaz sus obsesiones.", "Aprenda a retrasar la realización del ritual hasta que su ansiedad disminuya al menos hasta el 50% de la línea base inicial.", "Aprenda a cuestionar los contenidos de sus obsesiones mediante técnicas de tipo cognitivo (p.ej., la flecha descendente, etc.)"]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 70', 'En el tratamiento cognitivo-conductual del Trastorno Obsesivo Compulsivo, los experimentos conductuales:', '["Sustituyen a la exposición en vivo cuando esta técnica no puede aplicarse.", "Deben graduarse en cuanto a complejidad, al igual que se hace con la exposición.", "Sólo deben utilizarse en la fase de prevención de recaídas pues permiten predicciones más precisas.", "Son útiles para que el paciente pueda comprobar en su vida cotidiana que sus predicciones catastrofistas no se corresponden con la realidad."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 71', 'El estilo terapéutico más recomendable para el tratamiento cognitivo del Trastorno Obsesivo Compulsivo incluye, entre otras, las características siguientes:', '["La aplicación correcta de las técnicas de exposición con prevención de respuesta.", "Un empirismo colaborador y el uso del descubrimiento guiado.", "Utilizar a los familiares para convencer al paciente de que sus obsesiones no tienen sentido y que sus rituales le hacen perder tiempo.", "Un estilo directivo a la vez que tranquilizador, que promueva en el paciente la búsqueda de las causas de sus problemas en experiencias vitales tempranas negativas."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 72', '¿En cuál de las siguientes fases de la técnica de desensibilización y reprocesamiento por movimientos oculares (DRMO o EMDR) de Shapiro, para el tratamiento del estrés postraumático, el terapeuta realiza series de estimulación bilateral visual o táctil?:', '["Fase de Evaluación.", "Fase de Desensibilización.", "Fase de Exploración Corporal.", "Fase de Clausura."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 73', '¿Cuál de las siguientes técnicas se incluye en el programa de Reducción del Estrés Basado en Mindfulness (MBSR) propuesto por Kabat-Zinn?:', '["La activación diferencial.", "La autoexploración corporal.", "El modo hacer.", "La defunción cognitiva."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 74', '¿Cuál de los siguientes es un objetivo de los enfoques cognitivos en el tratamiento del Trastorno de Ansiedad Social (Fobia Social):', '["Incrementar, al principio las expectativas de pérdida de control sobre la propia conducta.", "Reducir las exposiciones a situaciones temidas hasta que la ansiedad anticipatoria sea mínima.", "Centrar la atención del sujeto en el aumento de su activación autónoma.", "Frenar la tendencia a establecer metas perfeccionistas."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 75', 'Uno de los objetivos terapéuticos de los actuales modelos de tratamiento del Trastorno de Ansiedad Social/Fobia Social (Clark, 2001) es corregir la excesiva atención centrada en uno mismo y la imagen distorsionada de la propia ejecución que presentan muchos pacientes. ¿Qué técnica proponen Clark y Beck con este fin?:', '["La técnica de reestructuración de imágenes.", "Video-feedback.", "Recuerdo autobiográfico de amenazas sociales pasadas.", "Meditación mindfulness."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 76', '¿Cuál de los siguientes se considera un predictor de mala respuesta al tratamiento de exposición en el Trastorno de Estrés Postraumático?:', '["Sentimientos de ira o culpa.", "Miedo intenso.", "Abusos sexuales.", "Insomnio severo."]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 77', '¿Cuál de los siguientes componentes forma parte del programa de intervención breve de Foa et al. (1995) para el tratamiento de víctimas de agresiones sexuales?:', '["Terapia de Aceptación y Compromiso.", "Entrenamiento en inoculación del estrés.", "Reestructuración cognitiva sobre las creencias irracionales acerca de la peligrosidad del mundo y la carencia de control sobre los hechos.", "Resolución de problemas."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 78', '¿En el tratamiento de qué trastorno proponen Foa y Rothbaum (1998) la metáfora de la “digestión psicológica” para explicar al paciente el objetivo de su intervención?:', '["Trastorno Obsesivo Compulsivo.", "Trastorno de Ansiedad Generalizada.", "Trastorno de Estrés Postraumático.", "Trastorno de Pánico."]'::jsonb, 2, null, false),
('PIR 15', 'Pregunta 79', '¿Cómo podemos mejorar la eficacia de la exposición en el tratamiento de las fobias específicas?:', '["Extendiendo el tiempo trascurrido entre sesiones.", "Prolongando la duración de las sesiones de exposición.", "Asociando a la terapia de exposición la toma de benzodiacepinas.", "Empleando la exposición imaginada en lugar de la exposición en vivo."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 80', 'A una mujer diagnosticada de Trastorno de Ansiedad Generalizada le solicitamos que no envíe continuos whassaps a su hija cuando ésta pasa fuera de casa el fin de semana, y no vaya a recogerla con su coche a la salida de la discoteca cada sábado. Estaríamos aplicando la técnica conocida como:', '["Inducción de la rumiación.", "Prevención de las conductas de preocupación.", "Evitación encubierta.", "Desfocalización del apego."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 81', 'Los fármacos de elección para el Trastorno de Ansiedad por Separación, son:', '["Los antidepresivos.", "Los antihistamínicos.", "Los beta-bloqueantes.", "Los antipsicóticos."]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 82', 'Para el tratamiento psicológico de niños con Déficit de Atención e Hipersensibilidad (TDAH) se incluye la técnica de restituir los efectos de conducta adaptada, lo que se conoce como:', '["Coste de respuesta.", "Resolución de problemas.", "Autorregulación.", "Sobrecorrección."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 83', '¿En qué trastorno infanto-juvenil es más adecuado emplear el procedimiento terapéutico de inversión del hábito?:', '["Hiperactividad.", "Bruxismo.", "Trastorno obsesivo compulsivo.", "Trastorno negativista desafiante."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 85', 'Los procedimientos de reforzamiento diferencial para el tratamiento de menores con comportamientos agresivos:', '["Suponen una forma de control de los antecedentes de la conducta.", "Incluyen el reforzamiento de omisión.", "Implican aislar al niño en una esquina de la sala.", "Consisten en reducir la estimulación aversiva."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 86', 'En el tratamiento cognitivo conductual de adolescentes con bulimia nerviosa (Fairburn, 1993), durante la fase de cambio alimentario:', '["Se establece una frecuencia semanal para pesarse.", "Se introducen algunos alimentos prohibidos.", "Se prescribe un patrón de comidas aleatorio.", "Se desaconseja que las pacientes anoten los alimentos que ingieren."]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 87', 'Sobre el uso del neurofeedback para el tratamiento del TDAH en niños, podemos afirmar que:', '["Utiliza los mecanismos del condicionamiento clásico.", "Se trata de un entrenamiento de la actividad eléctrica cerebral.", "Los juegos muy complejos y divertidos suelen ser más eficaces.", "Esta recomendado en casos con baja motivación hacia el tratamiento."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 88', 'En el entrenamiento básico en autoinstrucciones para niños y adolescentes, la fase en la que un modelo lleva a cabo una tarea mientras se habla en voz alta se denomina:', '["Guiado externo en voz alta.", "Autoinstrucciones enmascaradas.", "Modelado cognitivo.", "Autoinstrucciones encubiertas."]'::jsonb, 2, null, false),
('PIR 15', 'Pregunta 89', '¿Cuál de las siguientes terapias utiliza los procedimientos más y mejor evaluados en el tratamiento de los trastornos del espectro autista?:', '["Terapia Ocupacional.", "Terapia de integración auditiva.", "Terapias basadas en el análisis aplicado de la conducta.", "Hipnoterapia."]'::jsonb, 2, null, false),
('PIR 15', 'Pregunta 90', '¿Cuál es el tratamiento para la depresión infantil con un mayor apoyo empírico?:', '["Terapia familiar sistémica.", "Terapia de conducta.", "Terapia de juego.", "Relajación de Koepen."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 92', '¿Cuál de los siguientes constituye un objetivo del programa de tratamiento para menores víctimas de abuso sexual de Deblinger y Heflin?:', '["Enseñar al niño habilidades de expresión emocional.", "Olvidar el abuso.", "Aumentar la desconfianza de los menores hacia los adultos.", "Modificar la consulta sexual del menor."]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 93', '¿Cuál de los siguientes tratamientos conductuales es el adecuado para el abordaje del Trastorno por tics en la infancia?:', '["Entrenamiento en relajación.", "Inversión del hábito.", "Práctica masiva positiva.", "Manejo de contingencias."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 94', 'Cuál de las siguientes técnicas es considerada, según la evidencia disponible, un tratamiento bien establecido en el caso de las fobias infantiles:', '["El modelado participante.", "El entrenamiento en asertividad y HHSS.", "Las imágenes emotivas.", "La terapia basada en el juego."]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 95', '¿Cuál de las siguientes terapias fue desarrollada para la prevención de las recaídas depresivas en pacientes recuperados de uno o varios episodios graves de depresión?:', '["La terapia de aceptación y compromiso.", "La psicoterapia analítica-funcional.", "Sistema de análisis cognitivo-conductual de psicoterapia.", "Terapia cognitiva de la depresión basada en la conciencia plena."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 96', '¿Cuál de las siguientes técnicas se utiliza en la terapia cognitiva de la depresión con la finalidad de llevar a la conciencia los procesos de construcción de significados y las disposiciones subyacentes del paciente?:', '["Proyección temporal.", "Refocalización atencional.", "Desestructuración de sesgos.", "Flecha descendente."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 97', '¿A qué está destinada básicamente la primera fase (las cuatro primeras sesiones) de la terapia cognitiva de la depresión basada en la conciencia plena?:', '["A aprender a prestar atención con conciencia plena a diferentes aspectos.", "A aprender a detectar los cambios del estado de ánimo.", "A aprender a evitar la ocurrencia de pensamientos o sentimientos negativos.", "A aprender a elegir cuál es el mejor modo de responder ante los pensamientos o sentimientos negativos."]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 98', 'Para mejorar la adherencia al tratamiento en un paciente bipolar podemos realizar un contrato conductual, ¿Cuál de los siguientes aspectos NO se recomienda incluir en ese contrato?:', '["La definición de los objetivos del tratamiento.", "Las recompensas externas por la adherencia al tratamiento.", "Los factores que podrían interferir con el tratamiento.", "Los planes para reducir los obstáculos a la adherencia."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 99', 'Una técnica de gran relevancia en adicciones para motivar al paciente a realizar el tratamiento es:', '["La motivación catártica.", "El control estimular.", "La entrevista motivacional.", "La intención paradójica."]'::jsonb, 2, null, false),
('PIR 15', 'Pregunta 101', 'El tratamiento para las adicciones que busca el cambio terapéutico manipulando las contingencias naturales que pueden estar influyendo en el mantenimiento de la adicción, utilizando reforzadores para facilitar el proceso, se denomina:', '["Entrenamiento en autocontrol.", "Programa de prevención de recaídas.", "Entrenamiento en habilidades sociales.", "Programa de reforzamiento comunitario."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 102', 'Se han desarrollado tratamientos eficaces basados en el “mecanismo de ejecución conductual” para:', '["La esquizofrenia.", "La hipocondría.", "El trastorno por déficit de atención con hiperactividad.", "El juego patológico."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 103', 'Dentro del estudio orientado a la especificación de los ingredientes activos de un tratamiento psicológico, la estrategia que consiste en ir alterando no los ingredientes del tratamiento, sino la cuantía de los mismos (p.ej. la intensidad de un ingrediente) hasta conseguir la máxima eficacia se conoce como:', '["Tratamiento paramétrico.", "Construir el tratamiento.", "Tratamiento placebo.", "Desmantela el tratamiento."]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 104', 'Se considera que proporcionar una explicación racional que dé cuenta de los problemas del cliente o paciente y del tratamiento adecuado, es:', '["Un ingrediente terapéutico especifico.", "El proceder más habitual y central de los terapeutas sistémicos.", "Un factor común de la psicoterapia.", "Sólo se debe hacer cuando el cliente o paciente da muestra de resistencia."]'::jsonb, 2, null, false),
('PIR 15', 'Pregunta 105', '¿Quién formuló la propuesta de recoger información ya desde el primer contacto para la petición de consulta mediante la ficha telefónica, con el fin de elaborar hipótesis circulares?:', '["La escuela interaccional del Mental Research Institute (MRI).", "La escuela estratégica.", "El equipo de Milán liderado por M. Selvini-Palazzoli.", "La escuela estructural."]'::jsonb, 2, null, false),
('PIR 15', 'Pregunta 106', '¿Cuál es, según el psicoanálisis, el mecanismo de defensa consistente en sustituir el verdadero deseo de la persona que provoca ansiedad por otro que no la provoque?:', '["Proyección.", "Racionalización.", "Represión.", "Desplazamiento."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 107', 'Cuando en un estudio se comparan dos tratamientos se suele calcular la diferencia entre las medias obtenidas por cada tratamiento y se divide por la desviación típica conjunta ¿Cómo se denomina este cómputo?:', '["Metaanálisis.", "Tamaño del efecto.", "Porcentaje de pacientes recuperados.", "Índice de cambio fiable."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 108', 'Kelly diseño un procedimiento complejo en el que el cliente escribe una descripción de sí mismo (autocaracterización) y luego el terapeuta la re-escribe de forma que permita la exploración de otros esquemas alternativos. Se pide entonces al sujeto que ejecute el nuevo rol en su vida cotidiana durante dos semanas con la debida preparación y entrenamiento. Acabado este intenso periodo la nueva perspectiva adquirida permite que el cliente, con la ayuda del terapeuta, reestructure algunos de sus viejos esquemas supraordenados ¿Cómo se llama este procedimiento?:', '["Búsqueda de alternativas.", "Técnica de re-atribución.", "Análisis de costes y beneficios.", "Técnica de rol fijo."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 109', '¿Qué podemos decir de los estudios que pretenden determinar si un tratamiento psicológico produce efectos mensurables en amplias poblaciones de pacientes en su ambiente clínico real?:', '["Son estudios de efectividad.", "Son estudios que pretenden alcanzar el máximo de validez interna.", "Son estudios de eficacia.", "Se caracterizan por la asignación del azar de los pacientes."]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 110', 'En la Terapia Racional Emotiva el concepto de “ansiedad del yo” se refiere al malestar que experimentan las personas cuando:', '["Presentan creencias relacionadas con incompetencias o descalificación personal.", "Consideran que tienen que conseguir lo que desean.", "Consideran que su bienestar está amenazado.", "No toleran y les parecen terribles las situaciones desagradables de la vida."]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 111', 'Durante el entrenamiento en solución de problemas propio de la Terapia de Solución de Problemas, el principio de “aplazamiento del juicio” está indicado en la fase de:', '["Orientación hacia el problema.", "Toma de decisiones.", "Puesta en práctica de la alternativa elegida.", "Generación de alternativas de solución."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 112', 'Para planificar sesiones de exposición efectivas en un caso de fobia específica a un animal, hay que tener en cuenta que el ritmo de la exposición (también llamado gradiente de exposición):', '["No afecta a la eficacia de la técnica y dependerá de las preferencias del paciente.", "Afecta a la eficacia, siendo más eficaz la exposición gradual.", "Afecta a la eficacia, siendo más eficaz la exposición gradual simbólica.", "Afecta a la eficacia, siendo más eficaz la exposición masiva."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 113', 'La exposición con prevención de respuesta es actualmente una de las técnicas más útiles para el tratamiento de:', '["La ansiedad social.", "El trastorno obsesivo compulsivo.", "Las fobias específicas.", "La bulimia nerviosa."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 115', 'Los programas informáticos de generación de realidad virtual permiten desarrollar un tipo de:', '["Exposición guiada.", "Exposición simulada.", "Exposición simbólica.", "Desensibilización sistemática."]'::jsonb, 2, null, false),
('PIR 15', 'Pregunta 116', 'Señale cuál de las siguientes técnicas está más indicada en el tratamiento de la tricotilomanía:', '["La práctica masiva.", "La exposición con prevención de respuesta.", "La reversión del hábito.", "La intención paradójica."]'::jsonb, 2, null, false),
('PIR 15', 'Pregunta 117', 'En Terapia Cognitiva las creencias que tienen que ver con actitudes, reglas y supuestos que se formulan en términos proposicionales del tipo “si…entonces” se denominan:', '["Creencias nucleares.", "Creencias intermedias.", "Esquemas de control.", "Pensamientos automáticos."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 118', 'Las descalificaciones e insultos verbales pueden ser un ejemplo de:', '["Estímulos primarios.", "Estímulos disuasorios.", "Estímulos aversivos incondicionados.", "Estímulos aversivos condicionados."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 119', 'En el trastorno de personalidad límite, el tratamiento que mayor evidencia empírica ha recibido es:', '["La terapia cognitiva basada en los esquemas.", "La terapia centrada en el cliente.", "La terapia interpersonal.", "La terapia de conducta."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 120', 'La terapia cognitivo-conductual dialéctica, en el trastorno límite de la personalidad, ha obtenido buenos resultados en la mejoría de:', '["Las relaciones interpersonales inestables.", "Las conductas autolíticas y de suicidio.", "Los episodios de ira.", "La alteración de la identidad."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 121', 'La medicación antipsicótica para un primer episodio de psicosis después de la primera recuperación de los síntomas debería mantenerse durante un mínimo de:', '["Un año.", "Dos años.", "Cuatro años.", "Indefinidamente."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 122', 'En el apartado de Resultados de un informe de investigación, debemos:', '["Reflejar los datos resumidos y los resultados de los análisis estadísticos.", "Reproducir los datos brutos del estudio para permitir comprobaciones externas.", "Relacionar los resultados de los análisis con las hipótesis de trabajo y con otras investigaciones del campo de estudio.", "Describir cómo se ha realizado la investigación para garantizar su replicabilidad."]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 123', 'Para el tratamiento de los síntomas positivos persistentes en la esquizofrenia la terapia psicológica indicada es:', '["La intervención familiar.", "La psicoterapia psicodinámica.", "La rehabilitación cognitiva.", "La terapia cognitivo-conductual."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 124', 'En el tratamiento inicial de la esquizofrenia se recomienda la utilización de medicación antipsicótica de segunda generación porque:', '["Eliminan completamente la sintomatología negativa.", "No interfieren en el funcionamiento cognitivo.", "Tienen mejor tolerancia y un menor riesgo de discinesia tardía.", "No aumentan el riesgo de desarrollar un síndrome metabólico."]'::jsonb, 2, null, false),
('PIR 15', 'Pregunta 126', 'Qué modalidad de intervención familiar de la esquizofrenia tiene entre sus principales objetivos la reducción de la emoción expresada y del contacto con el paciente y el aumento de las redes sociales de la familia:', '["El modelo psicoeducativo de Anderson.", "El modelo sociofamiliar de Leff.", "El modelo cognitivo conductual de Tarrier.", "La terapia familiar conductual de Fallon."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 127', 'La aplicación de la terapia psicológica integrada de la esquizofrenia de Roder:', '["Mejora significativamente las variables cognitivas y conductuales tras el tratamiento.", "Mejora exclusivamente las variables cognitivas.", "Mejora las variables cognitivas significativamente mientras que sus efectos conductuales son inconsistentes.", "Mejora inconsistentemente las variables cognitivas y conductuales."]'::jsonb, 0, null, false),
('PIR 15', 'Pregunta 128', 'Entre los criterios de derivación de los trastornos alimentarios a un servicio de Urgencias de hospital general para recibir tratamiento médico urgente, se encuentra:', '["Pérdida de peso >50% en los últimos 6 meses (>30 % en los últimos 3 meses).", "Presencia de episodios bulímicos regulares, es decir, conductas de sobreingesta alimentaria y/o conductas purgativas persistentes (vomitos autoinducidos, abuso de laxantes y uso de diuréticos).", "Falta de conciencia de enfermedad.", "Amenorrea y astenia crónicas."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 129', 'La terapia interpersonal es uno de los tratamientos de elección para los casos de:', '["Anorexia nerviosa.", "Bulimia nerviosa.", "Obesidad con atracones (sobre todo para la pérdida de peso).", "Rumiación."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 130', 'Un procedimiento de modelado que combina exposición y actuación del modelo, instigadores verbales y físicos, ensayo de conducta y desensibilización in vivo, se denomina:', '["Modelado in vivo.", "Modelado pasivo.", "Modelado participante.", "Modelado simbólico."]'::jsonb, 2, null, false),
('PIR 15', 'Pregunta 131', 'La conducta de tomar un analgésico cuando tenemos dolor de cabeza es un comportamiento adquirido mediante un procedimiento de:', '["Reforzamiento positivo.", "Reforzamiento negativo.", "Reforzamiento diferencial de otras conductas.", "Moldeamiento."]'::jsonb, 1, null, false),
('PIR 15', 'Pregunta 132', 'Todos programas de entrenamiento en Habilidades Sociales suelen incluir 5 componentes básicos ¿Cuál de los siguientes elementos terapéuticos no está incluido entre esos cinco por no ser un elemento característico de este tipo de entrenamiento?:', '["Reforzamiento.", "Ensayo de conducta.", "Retroalimentación o feedback de la ejecución.", "Reestructuración cognitiva."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 133', 'La técnica de exposición interoceptiva es propia de los programas de intervención para:', '["La ansiedad generalizada.", "La fobia a la sangre.", "El trastorno obsesivo compulsivo.", "El trastorno de pánico."]'::jsonb, 3, null, false),
('PIR 15', 'Pregunta 134', 'En el caso de un trastorno de anorexia nerviosa, la primera alternativa de elección de tratamiento especializado es:', '["El ingreso hospitalario.", "El tratamiento ambulatorio.", "El hospital de día.", "Los pisos tutelados."]'::jsonb, 1, null, false),
